#!/bin/sh
# Installs Time Turner's system pieces. Run by the .deb's post-install script:
#   install.sh "/opt/Time Turner"
set -e
APP_DIR="$1"
[ -n "$APP_DIR" ] && [ -d "$APP_DIR" ] || { echo "time-turner: install.sh needs the app folder" >&2; exit 1; }
SYS="$APP_DIR/resources/system"
LIBDIR=/usr/lib/time-turner

# Launcher for the background service: the Electron binary in Node mode.
mkdir -p "$LIBDIR/shim"
cat > "$LIBDIR/time-turnerd" <<EOF
#!/bin/sh
# Generated by the Time Turner package. Starts the background service.
export ELECTRON_RUN_AS_NODE=1
exec "$APP_DIR/time-turner" "$APP_DIR/resources/app/src/daemon/index.js" "\$@"
EOF
chmod 755 "$LIBDIR/time-turnerd"

# a real copy, not a link into the app: the service and the start-up restore must find it even when the app moves
install -D -m 755 "$APP_DIR/resources/bin/restic" "$LIBDIR/bin/restic"
ln -sfn bin/restic "$LIBDIR/restic"
install -m 755 "$SYS/apt-hook" "$LIBDIR/apt-hook"

# restic's FUSE library looks for "fusermount"; Ubuntu ships fusermount3.
if [ -x /usr/bin/fusermount3 ] && ! command -v fusermount >/dev/null 2>&1; then
  ln -sf /usr/bin/fusermount3 "$LIBDIR/shim/fusermount"
fi

install -D -m 644 "$SYS/time-turnerd.service" /etc/systemd/system/time-turnerd.service
install -D -m 644 "$SYS/com.timeturner.Daemon.conf" /usr/share/dbus-1/system.d/com.timeturner.Daemon.conf
# palOS: let D-Bus start the service on demand (the app asks for it by name)
mkdir -p /usr/share/dbus-1/system-services
printf '[D-BUS Service]\nName=com.timeturner.Daemon\nExec=/bin/false\nUser=root\nSystemdService=time-turnerd.service\n' > /usr/share/dbus-1/system-services/com.timeturner.Daemon.service
install -D -m 644 "$SYS/com.timeturner.policy" /usr/share/polkit-1/actions/com.timeturner.policy
install -D -m 644 "$SYS/80time-turner" /etc/apt/apt.conf.d/80time-turner
install -D -m 755 "$SYS/initramfs/hook" /usr/share/initramfs-tools/hooks/time-turner
install -D -m 755 "$SYS/initramfs/local-bottom" /usr/share/initramfs-tools/scripts/local-bottom/time-turner

install -d -m 700 /etc/time-turner
install -d -m 755 /var/lib/time-turner
install -d -m 700 /var/cache/time-turner

# Remember the current kernels/release so the apt hook only reacts to changes.
ls -1 /boot/vmlinuz-* 2>/dev/null | sort > /var/lib/time-turner/apt-kernels || true
(. /etc/os-release && echo "$VERSION_ID") > /var/lib/time-turner/apt-release 2>/dev/null || true

# Start at every boot. palOS: also when installed into an image (no running systemd), which used to
# leave the service switched off, so Time Turner said its background service wasn't running.
systemctl enable time-turnerd.service >/dev/null 2>&1 || { mkdir -p /etc/systemd/system/multi-user.target.wants; ln -sf /etc/systemd/system/time-turnerd.service /etc/systemd/system/multi-user.target.wants/time-turnerd.service; }
# Start (or restart) the service now.
if [ -d /run/systemd/system ]; then
  systemctl daemon-reload || true
  systemctl reload dbus 2>/dev/null || systemctl reload dbus-broker 2>/dev/null || true
  systemctl enable time-turnerd.service >/dev/null 2>&1 || true
  systemctl restart time-turnerd.service || echo "time-turner: the background service did not start; see: journalctl -u time-turnerd" >&2
fi

# Add the restore step to the boot images (takes a little while).
if command -v update-initramfs >/dev/null 2>&1; then
  echo "time-turner: updating boot images…"
  update-initramfs -u -k all >/dev/null 2>&1 || echo "time-turner: update-initramfs failed; system restores will not work until it succeeds" >&2
fi
exit 0
